//! Differential tests against Privy's shamir-secret-sharing 0.0.4
//! (`vectors/lowki-shares/vectors.json`, generated by `gen.ts`).

use lowki_shares::{Error, Share, combine, combine_shares, field, split};
use rand_core::{CryptoRng, RngCore};
use serde::Deserialize;

const VECTORS: &str = include_str!("../../../vectors/lowki-shares/vectors.json");

#[derive(Deserialize)]
struct Vectors {
    log_table: String,
    exp_table: String,
    cases: Vec<Case>,
    too_few: Vec<TooFew>,
    privy_errors: Vec<PrivyError>,
}

#[derive(Deserialize)]
struct Case {
    secret: String,
    n: usize,
    t: usize,
    random: String,
    shares: Vec<String>,
    subsets: Vec<Subset>,
}

#[derive(Deserialize)]
struct Subset {
    idx: Vec<usize>,
    secret: String,
}

#[derive(Deserialize)]
struct TooFew {
    shares: Vec<String>,
    t: usize,
    secret: String,
    privy_result: String,
}

#[derive(Deserialize)]
struct PrivyError {
    shares: Vec<String>,
    error: String,
}

fn h(s: &str) -> Vec<u8> {
    hex::decode(s).unwrap()
}

fn vectors() -> Vectors {
    serde_json::from_str(VECTORS).unwrap()
}

/// Replays a recorded byte stream; panics if split asks for more than was recorded.
struct Replay {
    bytes: Vec<u8>,
    pos: usize,
}

impl RngCore for Replay {
    fn next_u32(&mut self) -> u32 {
        unimplemented!()
    }
    fn next_u64(&mut self) -> u64 {
        unimplemented!()
    }
    fn fill_bytes(&mut self, dest: &mut [u8]) {
        dest.copy_from_slice(&self.bytes[self.pos..self.pos + dest.len()]);
        self.pos += dest.len();
    }
    fn try_fill_bytes(&mut self, dest: &mut [u8]) -> Result<(), rand_core::Error> {
        self.fill_bytes(dest);
        Ok(())
    }
}
impl CryptoRng for Replay {}

/// Deterministic test RNG (xorshift64*), for Rust-only splits.
struct TestRng(u64);
impl RngCore for TestRng {
    fn next_u32(&mut self) -> u32 {
        self.next_u64() as u32
    }
    fn next_u64(&mut self) -> u64 {
        self.0 ^= self.0 >> 12;
        self.0 ^= self.0 << 25;
        self.0 ^= self.0 >> 27;
        self.0.wrapping_mul(0x2545_f491_4f6c_dd1d)
    }
    fn fill_bytes(&mut self, dest: &mut [u8]) {
        for b in dest {
            *b = (self.next_u64() >> 32) as u8;
        }
    }
    fn try_fill_bytes(&mut self, dest: &mut [u8]) -> Result<(), rand_core::Error> {
        self.fill_bytes(dest);
        Ok(())
    }
}
impl CryptoRng for TestRng {}

#[test]
fn field_matches_privy_tables() {
    let v = vectors();
    let log = h(&v.log_table);
    let exp = h(&v.exp_table);
    // Privy's mult/div, transcribed from src/index.ts
    let pmul = |a: u8, b: u8| -> u8 {
        if a == 0 || b == 0 {
            0
        } else {
            exp[(log[a as usize] as usize + log[b as usize] as usize) % 255]
        }
    };
    let pdiv = |a: u8, b: u8| -> u8 {
        if a == 0 {
            0
        } else {
            exp[(log[a as usize] as usize + 255 - log[b as usize] as usize) % 255]
        }
    };
    assert_eq!(exp[1], 0xe5, "generator");
    for a in 0..=255u8 {
        for b in 0..=255u8 {
            assert_eq!(field::mul(a, b), pmul(a, b), "mul {a} {b}");
            if b != 0 {
                assert_eq!(field::div(a, b), pdiv(a, b), "div {a} {b}");
            }
        }
    }
}

#[test]
fn split_replay_equals_privy() {
    let v = vectors();
    for (ci, c) in v.cases.iter().enumerate() {
        let mut rng = Replay { bytes: h(&c.random), pos: 0 };
        let shares = split(&h(&c.secret), c.n, c.t, &mut rng).unwrap();
        assert_eq!(rng.pos, rng.bytes.len(), "case {ci}: RNG consumption");
        assert_eq!(shares.len(), c.n);
        for (s, js) in shares.iter().zip(&c.shares) {
            assert_eq!(s.as_bytes(), h(js).as_slice(), "case {ci}: share bytes");
        }
    }
}

#[test]
fn privy_split_rust_combine() {
    let v = vectors();
    let mut checks = 0;
    for (ci, c) in v.cases.iter().enumerate() {
        let shares: Vec<Vec<u8>> = c.shares.iter().map(|s| h(s)).collect();
        for sub in &c.subsets {
            let pick: Vec<&[u8]> = sub.idx.iter().map(|&i| shares[i].as_slice()).collect();
            let got = combine(&pick, c.t).unwrap();
            assert_eq!(got.as_slice(), h(&sub.secret).as_slice(), "case {ci}");
            assert_eq!(sub.secret, c.secret);
            checks += 1;
            // one fewer than the threshold is rejected (Privy would return garbage)
            if pick.len() == c.t {
                assert_eq!(combine(&pick[..c.t - 1], c.t), Err(Error::TooFewShares));
            }
        }
    }
    assert!(checks >= 450, "{checks}");
}

#[test]
fn too_few_rejected_where_privy_returns_garbage() {
    let v = vectors();
    assert!(!v.too_few.is_empty());
    for c in &v.too_few {
        assert_ne!(c.privy_result, c.secret, "Privy returned the secret from t-1 shares?");
        let shares: Vec<Vec<u8>> = c.shares.iter().map(|s| h(s)).collect();
        assert_eq!(combine(&shares, c.t), Err(Error::TooFewShares));
        // and with the wrong (too low) threshold we reproduce Privy's (wrong) answer exactly
        if shares.len() >= 2 {
            let got = combine(&shares, shares.len()).unwrap();
            assert_eq!(hex::encode(got.as_slice()), c.privy_result);
        }
    }
}

#[test]
fn privy_error_inputs_rejected() {
    let v = vectors();
    for e in &v.privy_errors {
        assert!(!e.error.is_empty());
        let shares: Vec<Vec<u8>> = e.shares.iter().map(|s| h(s)).collect();
        let r = combine(&shares, 2);
        let want = if e.error.contains("duplicate") {
            Error::DuplicateX
        } else if e.error.contains("same byte length") {
            Error::LengthMismatch
        } else {
            Error::TooFewShares
        };
        assert_eq!(r, Err(want), "{}", e.error);
    }
}

#[test]
fn rust_only_rejections() {
    let mut rng = TestRng(7);
    assert_eq!(split(&[], 3, 2, &mut rng).unwrap_err(), Error::EmptySecret);
    assert_eq!(split(&[1], 1, 1, &mut rng).unwrap_err(), Error::InvalidShareCount);
    assert_eq!(split(&[1], 256, 2, &mut rng).unwrap_err(), Error::InvalidShareCount);
    assert_eq!(split(&[1], 3, 1, &mut rng).unwrap_err(), Error::InvalidThreshold);
    assert_eq!(split(&[1], 3, 4, &mut rng).unwrap_err(), Error::InvalidThreshold);
    let s = split(&[9; 32], 3, 2, &mut rng).unwrap();
    assert_eq!(combine(&s[..2], 1), Err(Error::InvalidThreshold));
    assert_eq!(combine(&s[..2], 256), Err(Error::InvalidThreshold));
    let mut zero_x = s[0].as_bytes().to_vec();
    *zero_x.last_mut().unwrap() = 0;
    assert_eq!(combine(&[zero_x.clone(), s[1].as_bytes().to_vec()], 2), Err(Error::ZeroX));
    assert_eq!(Share::from_bytes(&zero_x).unwrap_err(), Error::ZeroX);
    assert_eq!(Share::from_bytes(&[1]).unwrap_err(), Error::ShareTooShort);
    assert_eq!(combine(&[vec![1u8], vec![2u8]], 2), Err(Error::ShareTooShort));
    let many: Vec<Vec<u8>> = (0..256).map(|i| vec![0, i as u8]).collect();
    assert_eq!(combine(&many, 2), Err(Error::TooManyShares));
    // Debug never prints share bytes; errors carry no data
    let dbg = format!("{:?}", s[0]);
    assert!(dbg.starts_with("Share(x=") && !dbg.contains("0909"), "{dbg}");
    let round = Share::from_bytes(s[1].as_bytes()).unwrap();
    assert_eq!(combine_shares(&[s[0].clone(), round], 2).unwrap().as_slice(), &[9; 32]);
}

#[test]
fn interpolate_share_recreates_privy_shares() {
    use lowki_shares::interpolate_share;
    let v = vectors();
    for (ci, c) in v.cases.iter().enumerate() {
        let shares: Vec<Vec<u8>> = c.shares.iter().map(|s| h(s)).collect();
        // from the first t shares, re-derive every share (including the ones used)
        let base = &shares[..c.t];
        for want in &shares {
            let x = *want.last().unwrap();
            let got = interpolate_share(base, c.t, x).unwrap();
            assert_eq!(got.as_bytes(), want.as_slice(), "case {ci} x={x}");
        }
        assert_eq!(interpolate_share(base, c.t, 0).unwrap_err(), Error::ZeroX);
        assert_eq!(interpolate_share(&base[..c.t - 1], c.t, 1).unwrap_err(), Error::TooFewShares);
    }
}

/// Rust split -> Privy combine: writes out/rust-shares.json for `npm run verify-rust`.
#[test]
fn rust_split_export() {
    #[derive(serde::Serialize)]
    struct Out {
        secret: String,
        t: usize,
        shares: Vec<String>,
        subsets: Vec<Vec<usize>>,
    }
    let mut rng = TestRng(0x10c1_5ba7e5);
    let mut out = Vec::new();
    let mut params = TestRng(42);
    for i in 0..120usize {
        let (n, t, len) = match i {
            0 => (3, 2, 32),
            1 => (3, 2, 16),
            2 => (255, 255, 4),
            3 => (255, 2, 8),
            _ => {
                let n = 2 + (params.next_u32() % 30) as usize;
                let t = 2 + (params.next_u32() as usize % (n - 1));
                (n, t, 1 + (params.next_u32() % 70) as usize)
            }
        };
        let mut secret = vec![0u8; len];
        rng.fill_bytes(&mut secret);
        let shares = split(&secret, n, t, &mut rng).unwrap();
        // subsets: first t, last t, all
        let subsets = vec![(0..t).collect::<Vec<_>>(), (n - t..n).rev().collect(), (0..n).collect()];
        for sub in &subsets {
            let pick: Vec<&[u8]> = sub.iter().map(|&i| shares[i].as_bytes()).collect();
            assert_eq!(combine(&pick, t).unwrap().as_slice(), secret.as_slice());
        }
        out.push(Out {
            secret: hex::encode(&secret),
            t,
            shares: shares.iter().map(|s| hex::encode(s.as_bytes())).collect(),
            subsets,
        });
    }
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/../../vectors/lowki-shares/out");
    std::fs::create_dir_all(dir).unwrap();
    std::fs::write(format!("{dir}/rust-shares.json"), serde_json::to_string(&out).unwrap()).unwrap();
}
